#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8

__global__ void sgemm_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int N) {
    // Double-buffered shared memory tiles enable software pipelining:
    // global memory loads for the next K-tile are issued and overlapped
    // with compute on the current tile, hiding global memory latency.
    __shared__ float As[2][BK][BM];
    __shared__ float Bs[2][BK][BN];
    const int blockRow = blockIdx.y;
    const int blockCol = blockIdx.x;
    const int threadsPerRow = BN / TN; // 16
    const int threadRow = threadIdx.x / threadsPerRow; // 0..(BM/TM -1)
    const int threadCol = threadIdx.x % threadsPerRow;  // 0..(BN/TN -1)
    const int rowStart = blockRow * BM;
    const int colStart = blockCol * BN;
    float threadResults[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            threadResults[i][j] = 0.0f;
        }
    }
    const int tid = threadIdx.x;
    // Each thread loads exactly one float4 for A and one float4 for B per
    // K-tile (BM*BK/4 == BK*BN/4 == numThreads == 256).
    const int rA = tid / (BK / 4);
    const int c4A = tid % (BK / 4);
    const int rB = tid / (BN / 4);
    const int c4B = tid % (BN / 4);
    const int globalRowA = rowStart + rA;
    const int globalColB = colStart + c4B * 4;
    int buf = 0;
    // Prologue: load tile at k0 = 0 into buffer 0
    {
        int globalColA = 0 + c4A * 4;
        float4 valA;
        if (globalRowA < N && (globalColA + 3) < N) {
            valA = *reinterpret_cast<const float4*>(&A[(size_t)globalRowA * N + globalColA]);
        } else {
            valA.x = (globalRowA < N && globalColA     < N) ? A[(size_t)globalRowA * N + globalColA]     : 0.0f;
            valA.y = (globalRowA < N && globalColA + 1 < N) ? A[(size_t)globalRowA * N + globalColA + 1] : 0.0f;
            valA.z = (globalRowA < N && globalColA + 2 < N) ? A[(size_t)globalRowA * N + globalColA + 2] : 0.0f;
            valA.w = (globalRowA < N && globalColA + 3 < N) ? A[(size_t)globalRowA * N + globalColA + 3] : 0.0f;
        }
        int globalRowB = 0 + rB;
        float4 valB;
        if (globalRowB < N && (globalColB + 3) < N) {
            valB = *reinterpret_cast<const float4*>(&B[(size_t)globalRowB * N + globalColB]);
        } else {
            valB.x = (globalRowB < N && globalColB     < N) ? B[(size_t)globalRowB * N + globalColB]     : 0.0f;
            valB.y = (globalRowB < N && globalColB + 1 < N) ? B[(size_t)globalRowB * N + globalColB + 1] : 0.0f;
            valB.z = (globalRowB < N && globalColB + 2 < N) ? B[(size_t)globalRowB * N + globalColB + 2] : 0.0f;
            valB.w = (globalRowB < N && globalColB + 3 < N) ? B[(size_t)globalRowB * N + globalColB + 3] : 0.0f;
        }
        As[0][c4A * 4 + 0][rA] = valA.x;
        As[0][c4A * 4 + 1][rA] = valA.y;
        As[0][c4A * 4 + 2][rA] = valA.z;
        As[0][c4A * 4 + 3][rA] = valA.w;
        Bs[0][rB][c4B * 4 + 0] = valB.x;
        Bs[0][rB][c4B * 4 + 1] = valB.y;
        Bs[0][rB][c4B * 4 + 2] = valB.z;
        Bs[0][rB][c4B * 4 + 3] = valB.w;
    }
    __syncthreads();
    for (int k0 = 0; k0 < N; k0 += BK) {
        int curBuf = buf;
        int nextK0 = k0 + BK;
        bool hasNext = nextK0 < N;
        float4 valA, valB;
        if (hasNext) {
            int globalColA = nextK0 + c4A * 4;
            if (globalRowA < N && (globalColA + 3) < N) {
                valA = *reinterpret_cast<const float4*>(&A[(size_t)globalRowA * N + globalColA]);
            } else {
                valA.x = (globalRowA < N && globalColA     < N) ? A[(size_t)globalRowA * N + globalColA]     : 0.0f;
                valA.y = (globalRowA < N && globalColA + 1 < N) ? A[(size_t)globalRowA * N + globalColA + 1] : 0.0f;
                valA.z = (globalRowA < N && globalColA + 2 < N) ? A[(size_t)globalRowA * N + globalColA + 2] : 0.0f;
                valA.w = (globalRowA < N && globalColA + 3 < N) ? A[(size_t)globalRowA * N + globalColA + 3] : 0.0f;
            }
            int globalRowB = nextK0 + rB;
            if (globalRowB < N && (globalColB + 3) < N) {
                valB = *reinterpret_cast<const float4*>(&B[(size_t)globalRowB * N + globalColB]);
            } else {
                valB.x = (globalRowB < N && globalColB     < N) ? B[(size_t)globalRowB * N + globalColB]     : 0.0f;
                valB.y = (globalRowB < N && globalColB + 1 < N) ? B[(size_t)globalRowB * N + globalColB + 1] : 0.0f;
                valB.z = (globalRowB < N && globalColB + 2 < N) ? B[(size_t)globalRowB * N + globalColB + 2] : 0.0f;
                valB.w = (globalRowB < N && globalColB + 3 < N) ? B[(size_t)globalRowB * N + globalColB + 3] : 0.0f;
            }
        }
        #pragma unroll
        for (int kk = 0; kk < BK; kk++) {
            float4 a0 = *reinterpret_cast<const float4*>(&As[curBuf][kk][threadRow * TM]);
            float4 a1 = *reinterpret_cast<const float4*>(&As[curBuf][kk][threadRow * TM + 4]);
            float4 b0 = *reinterpret_cast<const float4*>(&Bs[curBuf][kk][threadCol * TN]);
            float4 b1 = *reinterpret_cast<const float4*>(&Bs[curBuf][kk][threadCol * TN + 4]);
            float regA[TM] = {a0.x, a0.y, a0.z, a0.w, a1.x, a1.y, a1.z, a1.w};
            float regB[TN] = {b0.x, b0.y, b0.z, b0.w, b1.x, b1.y, b1.z, b1.w};
            #pragma unroll
            for (int i = 0; i < TM; i++) {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    threadResults[i][j] += regA[i] * regB[j];
                }
            }
        }
        if (hasNext) {
            int nextBuf = 1 - curBuf;
            As[nextBuf][c4A * 4 + 0][rA] = valA.x;
            As[nextBuf][c4A * 4 + 1][rA] = valA.y;
            As[nextBuf][c4A * 4 + 2][rA] = valA.z;
            As[nextBuf][c4A * 4 + 3][rA] = valA.w;
            Bs[nextBuf][rB][c4B * 4 + 0] = valB.x;
            Bs[nextBuf][rB][c4B * 4 + 1] = valB.y;
            Bs[nextBuf][rB][c4B * 4 + 2] = valB.z;
            Bs[nextBuf][rB][c4B * 4 + 3] = valB.w;
            __syncthreads();
            buf = nextBuf;
        }
    }
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        int globalRow = rowStart + threadRow * TM + i;
        if (globalRow < N) {
            int globalCol0 = colStart + threadCol * TN;
            if (globalCol0 + 7 < N) {
                float4 c0 = make_float4(threadResults[i][0], threadResults[i][1], threadResults[i][2], threadResults[i][3]);
                float4 c1 = make_float4(threadResults[i][4], threadResults[i][5], threadResults[i][6], threadResults[i][7]);
                *reinterpret_cast<float4*>(&C[(size_t)globalRow * N + globalCol0]) = c0;
                *reinterpret_cast<float4*>(&C[(size_t)globalRow * N + globalCol0 + 4]) = c1;
            } else {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    int globalCol = globalCol0 + j;
                    if (globalCol < N) {
                        C[(size_t)globalRow * N + globalCol] = threadResults[i][j];
                    }
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");

    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    TORCH_CHECK(A.size(1) == N, "A must be square");
    TORCH_CHECK(B.size(0) == N && B.size(1) == N, "B must be square with same N as A");

    auto C = torch::empty({N, N}, A.options());

    dim3 blockDim((BM / TM) * (BN / TN), 1, 1);
    dim3 gridDim((N + BN - 1) / BN, (N + BM - 1) / BM, 1);

    sgemm_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
